const ACHIEVEMENTS={"primer_quiz": {"icon": "🧠", "label": "Primer quiz de los tres atajos superado"}, "flash_master": {"icon": "🃏", "label": "Las 16 tarjetas de las tres heurísticas exploradas"}, "clasif_pro": {"icon": "🗂️", "label": "Clasificador de sesgos por su heurística madre experto"}, "id_master": {"icon": "🔍", "label": "Identificador de gatillos y modos de fallo maestro"}, "reto_hero": {"icon": "🏆", "label": "Héroe del reto de los 30 segundos"}, "sopa_champ": {"icon": "🔤", "label": "Campeón de la sopa de los tres atajos"}, "eval_ace": {"icon": "🎓", "label": "Evaluación final aprobada con honores"}, "lect_master": {"icon": "📖", "label": "Las 30 preguntas de comprensión lectora respondidas"}, "full_xp": {"icon": "👑", "label": "Etapa 1 de la Ruta de la Brújula Torcida completada"}};
function unlockAchievement(id){if(!ACHIEVEMENTS[id])return;if(unlockedAch.includes(id))return;unlockedAch.push(id);sfx('ach');showToast(ACHIEVEMENTS[id].icon+' ¡Logro desbloqueado! '+ACHIEVEMENTS[id].label);launchConfetti();renderAchPanel();saveProgress();}
function renderAchPanel(){const list=document.getElementById('achList');list.innerHTML='';Object.entries(ACHIEVEMENTS).forEach(([id,a])=>{const div=document.createElement('div');div.className='ach-item'+(unlockedAch.includes(id)?'':' locked');div.innerHTML=`<span class="ach-icon">${a.icon}</span><span>${a.label}</span>`;list.appendChild(div);});}
