// ===================== FLASHCARD DATA =====================
const fcData=[{"w": "La heurística (el atajo)", "a": "🧭 <strong>Cambiar una pregunta difícil por una fácil:</strong> en vez de «¿qué tan probable es esto?», la cabeza contesta «¿a qué se parece?», «¿cuántos casos me vienen a la memoria?» o «¿cuánto se aleja de la cifra que acabo de oír?». Amos Tversky y Daniel Kahneman describieron las tres en «Judgment under Uncertainty: Heuristics and Biases» (Science, 1974)."}, {"w": "Representatividad", "a": "👥 Juzgar por <strong>parecido</strong>: se estima si algo pertenece a una categoría por lo mucho que se parece al retrato típico de esa categoría. Acierta a menudo y es gratis; falla porque el parecido no sabe <strong>cuántos hay</strong> de cada clase, ni cuántos casos se miraron, ni si el dato es fiable."}, {"w": "Disponibilidad", "a": "🧠 Juzgar la frecuencia por <strong>la facilidad con que vienen ejemplos a la memoria</strong>. Sirve cuando lo frecuente deja más huellas; falla cuando lo que se recuerda fácil lo es por reciente, por vívido o por haber salido en las noticias. Tversky y Kahneman la estudiaron aparte en «Availability» (Cognitive Psychology, 1973)."}, {"w": "Anclaje con ajuste insuficiente", "a": "⚓ Se parte de un número cualquiera y se ajusta desde ahí, siempre <strong>menos de lo que haría falta</strong>. En 1974 se enseñó con una rueda de la fortuna trucada: quienes vieron el 10 estimaron 25 por ciento de países africanos en la ONU, y quienes vieron el 65 estimaron 45. El número no significaba nada y aun así movió la respuesta."}, {"w": "La tasa base", "a": "📊 <strong>Cuántos hay de cada clase antes de mirar el caso.</strong> Es el dato que el parecido pisa: si de cada cien encargos así solo tres se terminan, la descripción entusiasta del candidato no cambia esa cuenta, solo la tapa. Kahneman y Tversky la midieron en «On the Psychology of Prediction» (Psychological Review, 1973)."}, {"w": "El problema de Linda", "a": "👩 La descripción de Linda hace que mucha gente juzgue <strong>más probable</strong> «cajera y feminista» que «cajera», cuando lo particular nunca puede ser más probable que lo general (Tversky y Kahneman, 1983). <strong>Estatus: cuestionado en su interpretación.</strong> Hertwig y Gigerenzer (1999) mostraron que buena parte del efecto se cae al preguntar «¿cuántas de cada cien?», porque «probable» también significa «plausible» en el habla común."}, {"w": "Insensibilidad al tamaño de la muestra", "a": "🏥 El parecido no distingue entre tres casos y trescientos, así que una muestra chica parece decir tanto como una grande. Por eso sorprende que el <strong>hospital pequeño</strong> tenga muchos más días de resultados extremos que el grande, siendo la misma proporción de fondo. Ejemplo central de representatividad en el artículo de 1974."}, {"w": "El miedo tras la noticia", "a": "📰 Hija de la disponibilidad: un caso contado con detalle deja un recuerdo que se levanta solo, y esa facilidad se confunde con frecuencia. Lichtenstein, Slovic, Fischhoff, Layman y Combs (1978) midieron cómo se abultan las causas de muerte espectaculares y se encogen las calladas."}, {"w": "El sesgo del superviviente", "a": "✈️ Disponibilidad por el lado del que no queda recuerdo: <strong>los casos que fracasaron no dejaron ejemplo que recordar</strong>. Abraham Wald lo razonó en 1943 para el Statistical Research Group de Columbia: los agujeros estaban en los aviones que volvieron, así que había que blindar justamente donde ellos NO los tenían."}, {"w": "La primera cifra en la mesa", "a": "💬 Hija del anclaje: quien dice el primer número pone el terreno, y todo lo que sigue son ajustes cortos alrededor de él. No se defiende discutiendo mejor ni siendo más listo: se defiende <strong>llevando la cifra propia escrita desde antes</strong> de entrar a la reunión."}, {"w": "La regresión a la media", "a": "📉 Después de un resultado extremo, lo que sigue tiende a quedar más cerca del promedio sin que nadie haya hecho nada. Francis Galton la describió en 1886 midiendo estaturas de padres e hijos: <strong>es una propiedad de los datos</strong>, no un premio ni un castigo."}, {"w": "El elogio que «daña»", "a": "🎖️ Los instructores de vuelo del ejemplo de 1974 juraban que felicitar empeoraba al alumno y regañarlo lo mejoraba. Lo que veían era regresión: tras un vuelo excelente casi siempre viene uno peor, y tras uno pésimo casi siempre viene uno mejor. <strong>No prueba que elogiar dañe: prueba que la estadística existe.</strong>"}, {"w": "Gatillo, ambiente y modo de fallo", "a": "🧰 La ficha de tres casillas con la que se estudia cada atajo en esta etapa. <strong>Gatillo:</strong> qué pregunta lo despierta. <strong>Ambiente:</strong> dónde acierta, porque un atajo no es un defecto sino una apuesta a que el mundo se porte de cierta manera. <strong>Modo de fallo:</strong> qué dato ignora cuando el mundo no se porta así."}, {"w": "Derivar un sesgo", "a": "🔗 La operación de esta etapa: tomar un sesgo con nombre propio y preguntarle qué juicio pedía, qué señal fácil se usó en su lugar y de cuál de los tres atajos sale esa señal. Quien termina lo hace con cualquier nombre del catálogo, <strong>o demuestra que ese nombre no añade nada</strong> a otro que ya estaba."}, {"w": "El nombre redundante", "a": "♻️ El zoológico tiene doscientas jaulas y bastantes menos animales: muchos «sesgos» son el mismo atajo con otra ropa y otro autor. La prueba es corta: si dos nombres comparten <strong>gatillo y modo de fallo</strong>, son el mismo sesgo contado dos veces."}, {"w": "Saberlo no inmuniza", "a": "⚠️ Conocer el nombre de un sesgo no lo apaga: Kahneman escribió en «Thinking, Fast and Slow» (2011) que su propia intuición seguía tan expuesta como antes de estudiarlos. Lo que cambia las cosas es <strong>cambiar el procedimiento</strong>: escribir la cifra antes de entrar, sacar la cuenta en frecuencias naturales, pedir la tasa base por costumbre y no por sospecha."}];
let fcIdx=0;
function upFC(){document.getElementById('fcInner').classList.remove('flipped');document.getElementById('fcW').textContent=fcData[fcIdx].w;document.getElementById('fcA').innerHTML=fcData[fcIdx].a;document.getElementById('fcCtr').textContent=(fcIdx+1)+' / '+fcData.length;}
