function nextFC(){sfx('click');fcIdx=(fcIdx+1)%fcData.length;upFC();}
function prevFC(){sfx('click');fcIdx=(fcIdx-1+fcData.length)%fcData.length;upFC();}

// ===================== QUIZ DATA =====================
const qzData=[{"q":"¿Qué hace una heurística cuando aparece una pregunta difícil?","o":["a) La deja sin contestar hasta tener datos","b) La cambia por una pregunta fácil y contesta esa","c) La divide en partes y las resuelve una por una","d) La consulta con alguien que sepa más"],"c":1,"e":"Ese cambio es el mecanismo: en vez de «¿qué tan probable es?», la cabeza contesta «¿a qué se parece?», «¿cuántos casos recuerdo?» o «¿cuánto se aleja de la cifra que oí?»."},{"q":"¿Cuáles son las tres heurísticas del artículo de 1974?","o":["a) Memoria, atención y lenguaje","b) Optimismo, pesimismo y prudencia","c) Inducción, deducción y analogía","d) Representatividad, disponibilidad y anclaje con ajuste insuficiente"],"c":3,"e":"Tversky y Kahneman las presentaron juntas en Science, 1974. De ellas sale casi todo el catálogo de sesgos con nombre propio."},{"q":"Un jurado del proyecto lee la descripción entusiasta de un candidato y olvida que de cien encargos así solo tres se terminan. ¿Qué falló?","o":["a) La tasa base, pisada por el parecido con el retrato típico","b) La memoria, que no guardó bien la descripción","c) El anclaje en la primera cifra que se dijo","d) La regresión a la media"],"c":0,"e":"Representatividad pura: el parecido no sabe cuántos hay de cada clase, y la tasa base es exactamente ese dato."},{"q":"¿Por qué el hospital pequeño tiene más días con proporciones extremas que el grande?","o":["a) Porque atiende a personas distintas","b) Porque sus registros son menos confiables","c) Porque las muestras chicas varían más, y el parecido no distingue entre tres casos y trescientos","d) Porque el azar prefiere los lugares chicos"],"c":2,"e":"Es la insensibilidad al tamaño de la muestra: el juicio por parecido ignora cuántos casos se miraron."},{"q":"En 1974, una rueda de la fortuna trucada mostró 10 a un grupo y 65 a otro antes de preguntar por los países africanos en la ONU. ¿Qué pasó?","o":["a) Nada: nadie hace caso a un número sin sentido","b) Los dos grupos dieron la misma estimación media","c) El grupo del 65 estimó más bajo, por desconfianza","d) El grupo del 10 estimó 25 por ciento y el del 65 estimó 45"],"c":3,"e":"El ancla movió la respuesta aunque todos habían visto girar la rueda: el ajuste desde el número inicial se queda corto."},{"q":"Una maestra sufre un robo y esa semana el equipo cree que los robos se dispararon. ¿De qué atajo es hija esa impresión?","o":["a) De la representatividad","b) De la disponibilidad: el caso reciente y vívido se levanta solo en la memoria","c) Del anclaje con ajuste insuficiente","d) De la regresión a la media"],"c":1,"e":"La facilidad para recordar un ejemplo se confunde con su frecuencia. La cuenta de cuántos incidentes hubo entre cuántas aulas dice otra cosa."},{"q":"Tres escuelas que siguen usando M.E.T.A.S cuentan que les funcionó, y se decide copiar lo que ellas hicieron. ¿Qué falta?","o":["a) Preguntarles con más detalle","b) Un contrato con esas tres escuelas","c) Las que lo dejaron: no dejaron ejemplo que recordar, y sin ellas la muestra son solo supervivientes","d) Nada: tres casos con éxito bastan"],"c":2,"e":"Sesgo del superviviente, hijo de la disponibilidad. Wald lo razonó en 1943: los agujeros que importan están en los aviones que no volvieron."},{"q":"El alumno que recibió el mejor puntaje y fue felicitado rinde peor la semana siguiente. ¿Qué prueba eso?","o":["a) Que la estadística existe: tras un resultado extremo lo siguiente tiende a acercarse al promedio","b) Que el elogio daña el rendimiento","c) Que el regaño funciona mejor","d) Que la prueba estaba mal hecha"],"c":0,"e":"Es regresión a la media, descrita por Galton en 1886. Los instructores de vuelo del ejemplo de 1974 cayeron justo aquí."},{"q":"¿Cómo se estudia cada heurística en esta etapa?","o":["a) Memorizando la lista completa de sus sesgos hijos","b) Por orden alfabético de sus nombres propios","c) Por el año en que se publicó cada uno","d) Con su gatillo, su ambiente y su modo de fallo"],"c":3,"e":"La lista de hijos se olvida y además crece sola; la ficha de tres casillas se aplica a un sesgo que uno nunca ha visto."},{"q":"¿Qué estatus tiene hoy el problema de Linda (1983)?","o":["a) Refutado por completo: nunca hubo efecto","b) Clásico cuestionado en su interpretación: Hertwig y Gigerenzer (1999) mostraron que parte del efecto es ambigüedad de la palabra «probable»","c) Clásico sólido, sin discusión abierta","d) Nunca se replicó con nadie"],"c":1,"e":"El efecto existe, pero se encoge mucho al preguntar «¿cuántas de cada cien?». Cada estudio de esta materia viaja con su etiqueta de estatus."}];
let qzIdx=0,qzSel=-1,qzDone=false;
function buildQz(){qzIdx=0;qzSel=-1;qzDone=false;showQz();}
function showQz(){if(qzIdx>=qzData.length){document.getElementById('qzQ').textContent='🎉 ¡Quiz completado!';document.getElementById('qzOpts').innerHTML='';fin('s-quiz');unlockAchievement('primer_quiz');return;}const q=qzData[qzIdx];document.getElementById('qzProg').textContent=`Pregunta ${qzIdx+1} de ${qzData.length}`;document.getElementById('qzQ').textContent=q.q;const opts=document.getElementById('qzOpts');opts.innerHTML='';q.o.forEach((o,i)=>{const b=document.createElement('button');b.className='qz-opt';b.textContent=o;b.onclick=()=>{if(qzDone)return;document.querySelectorAll('.qz-opt').forEach(x=>x.classList.remove('sel'));b.classList.add('sel');qzSel=i;sfx('click');};opts.appendChild(b);});qzDone=false;}
function checkQz(){if(qzSel<0)return fb('fbQz','Selecciona una respuesta.',false);qzDone=true;const opts=document.querySelectorAll('.qz-opt');if(qzSel===qzData[qzIdx].c){opts[qzSel].classList.add('correct');fb('fbQz','¡Correcto! +5 XP',true);if(!xpTracker.qz.has(qzIdx)){xpTracker.qz.add(qzIdx);pts(5);}sfx('ok');}else{opts[qzSel].classList.add('wrong');opts[qzData[qzIdx].c].classList.add('correct');fb('fbQz','Incorrecto. Revisa la respuesta correcta.',false);sfx('no');}setTimeout(()=>{qzIdx++;qzSel=-1;showQz();},1600);}
function resetQz(){sfx('click');qzIdx=0;qzSel=-1;qzDone=false;showQz();document.getElementById('fbQz').classList.remove('show');}

