const evalTFBank=[{"q": "Una heurística cambia una pregunta difícil por otra más fácil y contesta esa.", "a": true}, {"q": "Las tres heurísticas del artículo de 1974 son representatividad, disponibilidad y anclaje con ajuste insuficiente.", "a": true}, {"q": "La representatividad juzga por el parecido con el retrato típico de la categoría.", "a": true}, {"q": "El parecido con el retrato típico incluye el dato de cuántos hay de cada clase.", "a": false}, {"q": "La insensibilidad al tamaño de la muestra es hija de la disponibilidad.", "a": false}, {"q": "La disponibilidad estima la frecuencia por la facilidad con que vienen ejemplos a la memoria.", "a": true}, {"q": "El sesgo del superviviente aparece porque los casos que fracasaron no dejaron ejemplo que recordar.", "a": true}, {"q": "En el experimento de 1974, la rueda de la fortuna no movió las estimaciones de los participantes.", "a": false}, {"q": "El anclaje solo funciona cuando la cifra inicial es razonable y viene de alguien con autoridad.", "a": false}, {"q": "La regresión a la media explica que tras un puntaje extremo el siguiente se acerque al promedio.", "a": true}, {"q": "Que un alumno rinda peor después del elogio prueba que elogiar daña el rendimiento.", "a": false}, {"q": "Cada heurística se estudia con su gatillo, su ambiente y su modo de fallo.", "a": true}, {"q": "Si dos nombres de sesgo comparten gatillo y modo de fallo, se trata del mismo sesgo contado dos veces.", "a": true}, {"q": "El problema de Linda (1983) es un clásico cuestionado en su interpretación desde Hertwig y Gigerenzer (1999).", "a": true}, {"q": "Conocer el nombre de un sesgo basta para dejar de cometerlo.", "a": false}];
const evalMCBank=[{"q":"¿Qué hace una heurística ante una pregunta difícil?","o":["a) La aplaza hasta tener datos","b) La reparte entre varias personas","c) La cambia por una pregunta fácil y contesta esa","d) La resuelve con una fórmula"],"a":2},{"q":"¿Cuál de estas NO es una de las tres heurísticas de 1974?","o":["a) La aversión a la pérdida","b) La representatividad","c) La disponibilidad","d) El anclaje con ajuste insuficiente"],"a":0},{"q":"¿Qué señal usa la representatividad?","o":["a) La cifra que se oyó primero","b) La cantidad de ejemplos recordados","c) El costo de equivocarse","d) El parecido con el retrato típico"],"a":3},{"q":"¿Qué es la tasa base?","o":["a) El promedio de los últimos resultados","b) Cuántos hay de cada clase antes de mirar el caso","c) El precio mínimo aceptable","d) La probabilidad de que el caso sea vívido"],"a":1},{"q":"Un maestro descarta a una alumna callada para el concurso «porque no tiene perfil de concursante». ¿Qué sesgo es y de qué madre sale?","o":["a) Anclaje, hijo de la disponibilidad","b) Regresión a la media, hija del anclaje","c) Ceguera a la tasa base, hija de la representatividad","d) Sesgo del superviviente, hijo del anclaje"],"a":2},{"q":"¿Por qué el hospital pequeño registra más días con proporciones extremas?","o":["a) Porque atiende a otra clase de pacientes","b) Porque sus datos son menos confiables","c) Porque el azar castiga a los lugares chicos","d) Porque las muestras chicas varían más, y el parecido no distingue tres casos de trescientos"],"a":3},{"q":"¿Qué gatillo despierta a la disponibilidad?","o":["a) Una pregunta por la frecuencia o el peligro, con un caso reciente en la memoria","b) Una descripción detallada de una persona","c) Una cifra dicha en voz alta","d) Un resultado extremo seguido de otro normal"],"a":0},{"q":"¿Por qué el sesgo del superviviente es hijo de la disponibilidad?","o":["a) Porque los supervivientes se parecen entre sí","b) Porque los que fracasaron no dejaron ejemplo que recordar, y la memoria trabaja con una muestra recortada","c) Porque la primera historia que se oye ancla a las demás","d) Porque los supervivientes exageran sus resultados"],"a":1},{"q":"En 1974, ¿qué mostró la rueda de la fortuna trucada?","o":["a) Que la gente ignora los números sin sentido","b) Que las estimaciones mejoran con una cifra a la vista","c) Que los grupos coincidieron en su estimación","d) Que un número arbitrario mueve la estimación: 25 por ciento tras ver el 10 y 45 tras ver el 65"],"a":3},{"q":"¿Cómo se defiende alguien del ancla en una negociación?","o":["a) Llevando la cifra propia calculada en frío y escrita antes de entrar","b) Hablando primero de otra cosa","c) Recordándose que existe el anclaje","d) Pidiendo que el otro repita su número"],"a":0},{"q":"Un alumno saca su peor puntaje, lo regañan y la semana siguiente sube. ¿Qué explica mejor la subida?","o":["a) Que el regaño funciona","b) Que la prueba era más fácil","c) La regresión a la media: tras un resultado extremo lo siguiente se acerca al promedio","d) Que el alumno estudió el doble"],"a":2},{"q":"¿Con qué tres casillas se estudia cada heurística en esta etapa?","o":["a) Autor, año y revista","b) Gatillo, ambiente y modo de fallo","c) Nombre, sinónimo y ejemplo","d) Causa, efecto y remedio"],"a":1},{"q":"¿Cuándo se dice que un nombre de sesgo es redundante?","o":["a) Cuando es difícil de pronunciar","b) Cuando lo propuso un autor poco citado","c) Cuando no aparece en el artículo de 1974","d) Cuando otro nombre ya tiene el mismo gatillo y el mismo modo de fallo"],"a":3},{"q":"¿Qué estatus tiene el problema de Linda (Tversky y Kahneman, 1983)?","o":["a) Clásico sólido y sin discusión","b) Fraude retirado por la revista","c) Clásico cuestionado en su interpretación: Hertwig y Gigerenzer (1999) atribuyen parte del efecto a la ambigüedad de «probable»","d) Resultado nunca replicado por nadie"],"a":2},{"q":"¿Qué es lo que sí reduce el daño de estos atajos, según esta etapa?","o":["a) Cambiar el procedimiento: cifras escritas antes, cuentas en frecuencias naturales, tasa base pedida por costumbre","b) Conocer los nombres de los doscientos sesgos","c) Advertir al equipo antes de cada reunión","d) Confiar en la intuición de quien tiene más experiencia"],"a":0}];
const evalCPBank=[{"q": "Un atajo de juicio que cambia una pregunta difícil por otra fácil se llama ___.", "a": "heurística"}, {"q": "Juzgar por el parecido con el retrato típico es la heurística de la ___.", "a": "representatividad"}, {"q": "Juzgar la frecuencia por lo fácil que viene el ejemplo es la heurística de la ___.", "a": "disponibilidad"}, {"q": "Partir de una cifra y ajustar poco desde ella es el ___ con ajuste insuficiente.", "a": "anclaje"}, {"q": "El dato de cuántos hay de cada clase se llama tasa ___.", "a": "base"}, {"q": "Las tres heurísticas se publicaron en la revista Science en el año ___.", "a": "1974"}, {"q": "El sesgo del superviviente es hijo de la ___.", "a": "disponibilidad"}, {"q": "La insensibilidad al tamaño de la ___ es hija de la representatividad.", "a": "muestra"}, {"q": "Tras un resultado extremo, lo siguiente tiende a acercarse al ___.", "a": "promedio"}, {"q": "Que un alumno baje tras el elogio se explica por la ___ a la media.", "a": "regresión"}, {"q": "Lo que tiene que haber delante para que el atajo se dispare es su ___.", "a": "gatillo"}, {"q": "El dato que el atajo ignora cuando el ambiente cambia es su modo de ___.", "a": "fallo"}, {"q": "Si dos nombres comparten gatillo y modo de fallo, el segundo nombre es ___.", "a": "redundante"}, {"q": "En una negociación, quien dice la primera ___ pone el terreno de toda la conversación.", "a": "cifra"}, {"q": "El susto se contesta con la cuenta escrita en frecuencias ___.", "a": "naturales"}];
const evalPRBank=[{"term": "Heurística", "def": "Cambiar una pregunta difícil por una fácil"}, {"term": "Representatividad", "def": "Juzgar por parecido con el retrato típico"}, {"term": "Disponibilidad", "def": "Juzgar por lo fácil que viene el ejemplo"}, {"term": "Anclaje", "def": "Partir de una cifra y ajustar poco"}, {"term": "Tasa base", "def": "Cuántos hay de cada clase antes del caso"}, {"term": "Problema de Linda", "def": "Lo particular parece más probable que lo general"}, {"term": "Tamaño de la muestra", "def": "Tres casos no dicen lo que dicen trescientos"}, {"term": "Miedo tras la noticia", "def": "El caso vívido ocupa el lugar de la tasa"}, {"term": "Sesgo del superviviente", "def": "Los que fallaron no dejaron ejemplo"}, {"term": "Primera cifra", "def": "Quien abre pone el terreno de la reunión"}, {"term": "Regresión a la media", "def": "Tras el extremo, lo siguiente se acerca al promedio"}, {"term": "Gatillo", "def": "Lo que despierta al atajo"}, {"term": "Modo de fallo", "def": "El dato que el atajo ignora"}, {"term": "Nombre redundante", "def": "Mismo gatillo y mismo fallo que otro ya existente"}, {"term": "Frecuencias naturales", "def": "Uno de cada cuarenta, en vez de porcentajes"}];

function genEval(){sfx('click');_evalFormaSelector();const _selF=document.getElementById('evalFormaSel');if(_selF&&parseInt(_selF.value,10))evalFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_selF.value,10)));const cf=evalFormNum;const rng=_evalRng(cf);window._currentEvalForm=cf;evalFormNum=(evalFormNum%EVAL_FORMAS)+1;_evalFormaSelector();saveProgress();document.getElementById('eval-screen-title').textContent=`🎓 Evaluación Final · Forma ${cf} · Tres atajos generan el zoológico · Ruta de la Brújula Torcida`;evalAnsVisible=false;const out=document.getElementById('evalOut');out.innerHTML='';const bar=document.createElement('div');bar.className='eval-score-bar';bar.innerHTML=`<div><div class="esb-title">📊 Distribución de puntaje · 100 puntos</div><div class="esb-dist">Cada sección vale 25 puntos (5 preguntas × 5 pts)</div></div><div style="display:flex;gap:0.4rem;flex-wrap:wrap;"><span class="eval-score-pill esp-cp">Completar 25 pts</span><span class="eval-score-pill esp-tf">V/F 25 pts</span><span class="eval-score-pill esp-mc">Selección 25 pts</span><span class="eval-score-pill esp-pr">Pareados 25 pts</span></div>`;out.appendChild(bar);const cpItems=_pickF(evalCPBank,5,rng);const s1=document.createElement('div');s1.innerHTML='<div class="eval-section-title">I. Completar el espacio <span class="eval-pts">25 pts · 5 pts c/u</span></div>';cpItems.forEach((item,i)=>{const d=document.createElement('div');d.className='eval-item eval-auto-item';d.dataset.evalType='cp';d.dataset.evalIndex=i;const qHtml=item.q.replace('___',`<input class="eval-cp-input" type="text" data-cp="${i}" autocomplete="off">`);d.innerHTML=`<div class="eval-q"><span class="eval-num">${i+1}</span><span class="eval-q-text">${qHtml}</span></div><div class="eval-answer">${item.a}</div><div class="eval-item-feedback" id="evalFbCp${i}" aria-live="polite"></div>`;s1.appendChild(d);});out.appendChild(s1);const tfItems=_pickF(evalTFBank,5,rng);const s2=document.createElement('div');s2.innerHTML='<div class="eval-section-title">II. Verdadero o Falso <span class="eval-pts">25 pts · 5 pts c/u</span></div>';tfItems.forEach((item,i)=>{const d=document.createElement('div');d.className='eval-item eval-auto-item';d.dataset.evalType='tf';d.dataset.evalIndex=i;d.innerHTML=`<div class="eval-q"><span class="eval-num">${i+6}</span><span class="eval-q-text">${item.q}</span></div><div class="eval-tf-opts"><label class="eval-tf-opt"><input type="radio" name="tf${i}" value="true"> Verdadero</label><label class="eval-tf-opt"><input type="radio" name="tf${i}" value="false"> Falso</label></div><div class="eval-answer">${item.a?'Verdadero':'Falso'}</div><div class="eval-item-feedback" id="evalFbTf${i}" aria-live="polite"></div>`;s2.appendChild(d);});out.appendChild(s2);const mcItems=_pickF(evalMCBank,5,rng);const s3=document.createElement('div');s3.innerHTML='<div class="eval-section-title">III. Selección Múltiple <span class="eval-pts">25 pts · 5 pts c/u</span></div>';mcItems.forEach((item,i)=>{const d=document.createElement('div');d.className='eval-item eval-auto-item';d.dataset.evalType='mc';d.dataset.evalIndex=i;const optsHtml=item.o.map((op,oi)=>`<label class="eval-mc-opt"><input type="radio" name="mc${i}" value="${oi}"> ${op}</label>`).join('');d.innerHTML=`<div class="eval-q"><span class="eval-num">${i+11}</span><span class="eval-q-text">${item.q}</span></div><div class="eval-mc-opts">${optsHtml}</div><div class="eval-answer">${item.o[item.a]}</div><div class="eval-item-feedback" id="evalFbMc${i}" aria-live="polite"></div>`;s3.appendChild(d);});out.appendChild(s3);const prItems=_pickF(evalPRBank,5,rng);let shuffledDefs=_shuffleF(prItems,rng);let _prTries=0;while(shuffledDefs.some((df,ix)=>df.def===prItems[ix].def)&&_prTries<20){shuffledDefs=_shuffleF(shuffledDefs,rng);_prTries++;}const letters=['A','B','C','D','E'];const s4=document.createElement('div');s4.innerHTML='<div class="eval-section-title">IV. Términos Pareados <span class="eval-pts">25 pts · 5 pts c/u</span></div>';const matchCard=document.createElement('div');matchCard.className='eval-item';let colLeft='<div class="eval-match-col"><h4>📌 Términos</h4>';prItems.forEach((item,i)=>{colLeft+=`<div class="eval-match-item"><span class="eval-match-letter">${i+16}.</span> <select class="eval-match-select" data-pr="${i}" aria-label="Respuesta pareada ${i+16}"><option value="">?</option>${letters.map(l=>`<option value="${l}">${l}</option>`).join('')}</select> ${item.term}</div>`;});colLeft+='</div>';let colRight='<div class="eval-match-col"><h4>🔑 Definiciones</h4>';shuffledDefs.forEach((item,i)=>{colRight+=`<div class="eval-match-item"><span class="eval-match-letter">${letters[i]}.</span> ${item.def}</div>`;});colRight+='</div>';const ansKey=prItems.map((item,i)=>{const letter=letters[shuffledDefs.findIndex(d=>d.def===item.def)];return`${i+16}→${letter}`;}).join(' · ');matchCard.innerHTML=`<div class="eval-match-grid">${colLeft}${colRight}</div><div class="eval-answer" style="display:none;">${ansKey}</div><div class="eval-item-feedback" id="evalFbPr" aria-live="polite"></div>`;s4.appendChild(matchCard);out.appendChild(s4);window._evalPrintData={tf:tfItems,mc:mcItems,cp:cpItems,pr:{terms:prItems,shuffledDefs,letters}};const autoPanel=document.createElement('div');autoPanel.id='evalAutoResult';autoPanel.className='eval-auto-result';autoPanel.innerHTML='<strong>🧮 Evaluación interactiva:</strong> responde en pantalla y presiona <em>Calificar prueba</em>. La impresión conserva el formato original sin respuestas digitadas.';out.appendChild(autoPanel);fin('s-evaluacion');}
function toggleEvalAns(){evalAnsVisible=!evalAnsVisible;document.querySelectorAll('#evalOut .eval-answer').forEach(el=>el.style.display=evalAnsVisible?'block':'none');sfx('click');}
function normalizeEvalAnswer(v){return(v||'').toString().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/\s+/g,' ').replace(/[()]/g,'').trim();}
function isCpCorrect(student,expected){const s=normalizeEvalAnswer(student);const e=normalizeEvalAnswer(expected);if(!s)return false;const variants=new Set([e]);if(e.includes(' '))e.split(' ').forEach(x=>x&&variants.add(x));return variants.has(s)||e.replace(/[^a-z0-9]/g,'')===s.replace(/[^a-z0-9]/g,'');}
function setEvalFeedback(id,ok,msg){const el=document.getElementById(id);if(!el)return;el.textContent=msg;el.className='eval-item-feedback '+(ok?'eval-ok':'eval-no');}
function gradeEval(){if(!window._evalPrintData){showToast('⚠️ Genera una evaluación primero');return;}sfx('click');const d=window._evalPrintData;let total=0;const detail={cp:0,tf:0,mc:0,pr:0};d.cp.forEach((it,i)=>{const input=document.querySelector(`[data-cp="${i}"]`);const ok=isCpCorrect(input?input.value:'',it.a);if(input){input.classList.toggle('eval-input-ok',ok);input.classList.toggle('eval-input-no',!ok);}if(ok){detail.cp++;total+=5;}setEvalFeedback('evalFbCp'+i,ok,ok?'Correcto. +5 pts':'Revisar. Respuesta esperada: '+it.a);});d.tf.forEach((it,i)=>{const selected=document.querySelector(`input[name="tf${i}"]:checked`);const ok=!!selected&&(selected.value==='true')===it.a;if(ok){detail.tf++;total+=5;}setEvalFeedback('evalFbTf'+i,ok,ok?'Correcto. +5 pts':'Revisar. Respuesta esperada: '+(it.a?'Verdadero':'Falso'));});d.mc.forEach((it,i)=>{const selected=document.querySelector(`input[name="mc${i}"]:checked`);const ok=!!selected&&Number(selected.value)===it.a;if(ok){detail.mc++;total+=5;}setEvalFeedback('evalFbMc'+i,ok,ok?'Correcto. +5 pts':'Revisar. Respuesta esperada: '+it.o[it.a]);});const expectedLetters=d.pr.terms.map(it=>d.pr.letters[d.pr.shuffledDefs.findIndex(df=>df.def===it.def)]);expectedLetters.forEach((letter,i)=>{const sel=document.querySelector(`[data-pr="${i}"]`);const ok=!!sel&&sel.value===letter;if(sel){sel.classList.toggle('eval-input-ok',ok);sel.classList.toggle('eval-input-no',!ok);}if(ok){detail.pr++;total+=5;}});const prMsg=`Pareados: ${detail.pr}/5 correctos. ${detail.pr===5?'Excelente. +25 pts':'Clave: '+expectedLetters.map((l,i)=>(i+16)+'→'+l).join(' · ')}`;setEvalFeedback('evalFbPr',detail.pr===5,prMsg);const result=document.getElementById('evalAutoResult');if(result){result.className='eval-auto-result '+(total>=70?'eval-auto-pass':'eval-auto-risk');result.innerHTML=`<strong>Resultado automático: ${total}/100 puntos</strong><br><span>Completar: ${detail.cp*5}/25 · V/F: ${detail.tf*5}/25 · Selección: ${detail.mc*5}/25 · Pareados: ${detail.pr*5}/25</span><br><em>Este resultado es solo para revisión en pantalla; la impresión conserva el formato limpio para papel.</em>`;}if(total>=70){pts(8);showToast('🎯 Evaluación calificada: '+total+'/100');}else showToast('🧮 Evaluación calificada: '+total+'/100. Revisa las respuestas marcadas.');}
function printEval(){if(!window._evalPrintData){showToast('⚠️ Genera una evaluación primero');return;}sfx('click');const forma=window._currentEvalForm||1;const d=window._evalPrintData;let s1=`<div class="sec-title"><span>I. Completar el espacio</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 25%</span></div></div>`;d.cp.forEach((it,i)=>{const q=it.q.replace('___','<span class="cp-blank"></span>');s1+=`<div class="cp-row"><span class="qn">${i+1}.</span><span class="cp-text">${q}</span></div>`;});let s2=`<div class="sec-title"><span>II. Verdadero o Falso</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 25%</span></div></div>`;d.tf.forEach((it,i)=>{s2+=`<div class="tf-row"><span class="qn">${i+6}.</span><span class="tf-blank"></span><span class="tf-text">${it.q}</span></div>`;});let s3=`<div class="sec-title"><span>III. Selección Múltiple</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 25%</span></div></div><div class="mc-grid">`;d.mc.forEach((it,i)=>{const opts=it.o.map((op,oi)=>`<label class="mc-opt"><input type="radio" name="mcp${i}"> ${op}</label>`).join('');s3+=`<div class="mc-item"><div class="mc-q"><span class="qn">${i+11}.</span><span>${it.q}</span></div><div class="mc-opts">${opts}</div></div>`;});s3+=`</div>`;let colL='<div class="pr-col"><div class="pr-head">📌 Términos</div>';d.pr.terms.forEach((it,i)=>{colL+=`<div class="pr-item"><span class="pr-num">${i+16}.</span><span class="pr-line"></span>${it.term}</div>`;});colL+='</div>';let colR='<div class="pr-col"><div class="pr-head">🔑 Definiciones</div>';d.pr.shuffledDefs.forEach((it,i)=>{colR+=`<div class="pr-item"><span class="pr-num">${d.pr.letters[i]}.</span>${it.def}</div>`;});colR+='</div>';let s4=`<div class="pr-section"><div class="sec-title"><span>IV. Términos Pareados</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 25%</span></div></div><div class="pr-grid">${colL}${colR}</div></div>`;let pR='';pR+=`<div class="p-sec"><div class="p-ttl">I. Completar</div><table class="p-tbl">`;d.cp.forEach((it,i)=>{pR+=`<tr><td class="pn">${i+1}.</td><td class="pa">${it.a}</td></tr>`;});pR+=`</table></div><div class="p-sec"><div class="p-ttl">II. V o F</div><table class="p-tbl">`;d.tf.forEach((it,i)=>{pR+=`<tr><td class="pn">${i+6}.</td><td class="pa">${it.a?'V':'F'}</td></tr>`;});pR+=`</table></div><div class="p-sec"><div class="p-ttl">III. Selección</div><table class="p-tbl">`;d.mc.forEach((it,i)=>{pR+=`<tr><td class="pn">${i+11}.</td><td class="pa">${it.o[it.a]}</td></tr>`;});pR+=`</table></div><div class="p-sec"><div class="p-ttl">IV. Pareados</div><table class="p-tbl">`;d.pr.terms.forEach((it,i)=>{const l=d.pr.letters[d.pr.shuffledDefs.findIndex(df=>df.def===it.def)];pR+=`<tr><td class="pn">${i+16}.</td><td class="pa">${i+16}→${l}</td></tr>`;});pR+=`</table></div>`;const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>Evaluación Tres atajos generan el zoológico · Ruta de la Brújula Torcida · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.12rem 0.4rem;margin:0.22rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #3b3a86;background:#ece9fb;color:#3b3a86;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#3b3a86;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:58px;border-bottom:1.5px solid #3b3a86;height:12px;}.obt-pct{white-space:nowrap;}.qn{font-weight:700;min-width:22px;flex-shrink:0;}.tf-row{display:flex;align-items:baseline;gap:0.3rem;font-size:10.5pt;line-height:1.3;padding:0.13rem 0.2rem;border-bottom:1px solid #eee;}.tf-blank{display:inline-block;min-width:40px;border-bottom:1.5px solid #111;flex-shrink:0;margin:0 0.18rem;}.tf-text{flex:1;}.mc-item{border:1px solid #ddd;border-radius:4px;padding:0.14rem 0.35rem;margin-bottom:0.1rem;break-inside:avoid;page-break-inside:avoid;}.mc-q{font-size:10.5pt;line-height:1.3;display:flex;gap:0.28rem;margin-bottom:0.07rem;}.mc-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.1rem 0.5rem;}.mc-opts{display:grid;grid-template-columns:repeat(4,1fr);gap:0.04rem 0.15rem;margin-left:0.8rem;}.mc-opt{font-size:9pt;display:flex;align-items:center;gap:0.15rem;}.mc-opt input{width:10px;height:10px;flex-shrink:0;}.cp-row{display:flex;align-items:baseline;gap:0.3rem;font-size:10.5pt;line-height:1.3;padding:0.13rem 0.2rem;border-bottom:1px solid #eee;}.cp-text{flex:1;}.cp-blank{display:inline-block;min-width:150px;border-bottom:1.5px solid #111;margin:0 0.12rem;}.pr-section{margin-top:0.1rem;}.pr-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.08rem 0.4rem;margin-top:0.08rem;}.pr-head{font-size:9pt;font-weight:700;color:#555;margin-bottom:0.1rem;}.pr-item{font-size:10.5pt;padding:0.1rem 0.28rem;background:#ece9fb;border-radius:3px;margin-bottom:0.07rem;display:flex;align-items:center;gap:0.2rem;line-height:1.2;break-inside:avoid;page-break-inside:avoid;}.pr-num{font-weight:700;color:#3b3a86;min-width:19px;flex-shrink:0;}.pr-line{display:inline-block;min-width:19px;border-bottom:1.5px solid #111;margin-right:0.14rem;flex-shrink:0;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.22rem;padding:0.15rem 0;page-break-before:avoid;break-before:avoid;color:#3b3a86;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #3b3a86;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.25rem 0.4rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.15rem;}.p-tbl{width:100%;border-collapse:collapse;font-size:7.5pt;}.p-tbl tr{border-bottom:1px dotted #ddd;}.p-tbl td{padding:0.07rem 0.12rem;vertical-align:top;}.pn{font-weight:700;width:16px;color:#555;}.pa{color:#007a00;font-weight:600;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Final · Tres atajos generan el zoológico · Ruta de la Brújula Torcida · Etapa 1 · Sesgo cognitivo</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Instituto:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · Cada respuesta vale 5 puntos</p></div>${s1}${s2}${s3}${s4}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100%</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: Evaluación Final · Tres atajos generan el zoológico · Ruta de la Brújula Torcida · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 4 secciones × 5 preguntas × 5 pts c/u</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;const win=window.open('','_blank','');if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);}

