// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y": "1886", "icon": "📉", "label": "Galton", "text": "Francis Galton publica <strong>«Regression towards Mediocrity in Hereditary Stature»</strong> y describe que tras un valor extremo lo siguiente se acerca al promedio. <strong>Por qué importa aquí:</strong> casi un siglo después, la falta de esta idea seguirá produciendo causas inventadas."}, {"y": "1943", "icon": "✈️", "label": "Wald", "text": "Abraham Wald razona para el <strong>Statistical Research Group</strong> de Columbia que los agujeros de los aviones que volvieron señalan justamente donde NO hay que blindar. <strong>Por qué importa aquí:</strong> es el sesgo del superviviente antes de tener nombre, y es disponibilidad por el lado de lo que no dejó recuerdo."}, {"y": "1973", "icon": "🧠", "label": "Dos artículos", "text": "Tversky y Kahneman publican <strong>«Availability»</strong> (Cognitive Psychology) y <strong>«On the Psychology of Prediction»</strong> (Psychological Review). <strong>Por qué importa aquí:</strong> quedan medidas por separado la facilidad del recuerdo y la ceguera a la tasa base, las dos piezas que el artículo siguiente juntará."}, {"y": "1974", "icon": "🧭", "label": "Las tres juntas", "text": "<strong>«Judgment under Uncertainty: Heuristics and Biases»</strong>, en Science: representatividad, disponibilidad y anclaje con ajuste insuficiente, con la rueda de la fortuna y los instructores de vuelo dentro. <strong>Estatus: clásico sólido.</strong> Es el plano del que sale casi todo el zoológico."}, {"y": "1978", "icon": "📰", "label": "Lo que da miedo", "text": "Lichtenstein, Slovic, Fischhoff, Layman y Combs miden en <strong>«Judged Frequency of Lethal Events»</strong> cómo se abultan las causas de muerte espectaculares y se encogen las calladas. <strong>Por qué importa aquí:</strong> es disponibilidad con números, y explica el miedo que llega detrás de una noticia."}, {"y": "1983", "icon": "👩", "label": "Linda", "text": "Tversky y Kahneman publican el <strong>problema de Linda</strong> (Psychological Review): la descripción hace que «cajera y feminista» parezca más probable que «cajera». <strong>Por qué importa aquí:</strong> es representatividad llevada al extremo, y es también el estudio más discutido de la lista."}, {"y": "1999", "icon": "⚖️", "label": "La réplica", "text": "Hertwig y Gigerenzer muestran que buena parte del efecto de Linda se cae al preguntar <strong>«¿cuántas de cada cien?»</strong>, porque «probable» también significa «plausible». <strong>Estatus: clásico cuestionado en su interpretación.</strong> Kahneman recogería la discusión en «Thinking, Fast and Slow» (2011), donde escribió además que su propia intuición no había mejorado."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ============ SIMULACIÓN: EL SUSTO ANTES DE LA CUENTA ============
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(sacoLaCuenta){sfx(sacoLaCuenta?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(sacoLaCuenta){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">📊</span><span class="ms-text"><strong>Escribiste la cuenta antes de votar:</strong> un incidente en cuarenta aulas durante ocho meses. La tasa cabe en una línea y se puede poner al lado de lo que cuesta la medida: cuarenta horas de trabajo y las aulas sin señal que quedarían fuera.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🧭</span><span class="ms-text"><strong>La reunión discutió la tasa y no el susto:</strong> se dejó el APK sin conexión, se puso el bloqueo por clave en el aparato y quedó apuntada la cuenta, para volver a mirarla cuando haya un segundo incidente.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">😰</span><span class="ms-text"><strong>Se decidió con el caso de la semana:</strong> se suspendió el APK sin conexión el viernes. Cuarenta horas de trabajo, las aulas sin señal fuera del proyecto, y nadie llegó a escribir cuántos incidentes hubo entre cuántas aulas.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🧠</span><span class="ms-text"><strong>Se compró tranquilidad, no seguridad:</strong> la facilidad para recordar el robo hizo de tasa, que es exactamente la disponibilidad trabajando. Cuando el recuerdo se enfríe, la medida seguirá puesta y su costo también.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
// Las llaves del laboratorio (esperado, paradoja, utilidad, ruina) se HEREDAN
// del molde a propósito: los botones del HTML llaman labShowParte('esperado')
// etc., y renombrarlas aquí sin tocar ese archivo rompería el laboratorio en
// silencio. El nombre visible sale de cada «nombre», nunca de la llave. En
// esta etapa el reparto es: esperado = representatividad, paradoja =
// disponibilidad, utilidad = anclaje, ruina = regresión a la media.
const parteData={"esperado": {"nombre": "Representatividad", "icon": "👥", "estructura": {"title": "Qué es", "info": "• Juzgar por <strong>parecido</strong> con el retrato típico de la categoría<br>• La pregunta difícil («¿qué tan probable es?») se cambia por una fácil («¿a qué se parece?»)<br>• Es la primera de las tres heurísticas de <strong>Tversky y Kahneman (Science, 1974)</strong><br>• De ella salen la ceguera a la tasa base, el problema de Linda y la insensibilidad al tamaño de la muestra"}, "funcion": {"title": "Cómo se reconoce", "info": "• <strong>Gatillo:</strong> hay un retrato, una descripción o un caso delante, y hay que clasificarlo o pronosticarlo<br>• <strong>Ambiente donde acierta:</strong> cuando el parecido y la frecuencia van juntos, que es buena parte de la vida diaria<br>• Se nota en frases del tipo «tiene toda la pinta», «es el perfil exacto»<br>• Y en historias que parecen más probables cuanto más detalles traen"}, "enfermedades": {"title": "Dónde se cae", "info": "• <strong>Modo de fallo:</strong> el parecido no sabe cuántos hay de cada clase (la tasa base)<br>• Tampoco sabe cuántos casos se miraron: tres aulas parecen decir lo mismo que trescientas<br>• Ni si el dato es fiable: una descripción vaga produce la misma confianza que una buena<br>• Y premia la historia coherente: añadir un detalle la vuelve menos probable, no más"}, "cuidados": {"title": "En esta casa", "info": "• Antes de decidir sobre una persona se pide la <strong>tasa base</strong>: de cada cien casos así, ¿cuántos salieron bien?<br>• El entusiasmo de la primera reunión no cuenta como dato, porque lo produjeron también los que fallaron<br>• Y si hay que apostar por alguien, se compra un dato propio: una prueba corta pagada"}}, "paradoja": {"nombre": "Disponibilidad", "icon": "🧠", "estructura": {"title": "Qué es", "info": "• Estimar la frecuencia por <strong>la facilidad con que vienen ejemplos a la memoria</strong><br>• La pregunta difícil («¿cada cuánto pasa?») se cambia por «¿cuántos casos recuerdo?»<br>• Tversky y Kahneman la midieron en <strong>«Availability» (Cognitive Psychology, 1973)</strong> y la incluyeron en el artículo de 1974<br>• De ella salen el miedo tras la noticia y el sesgo del superviviente"}, "funcion": {"title": "Cómo se reconoce", "info": "• <strong>Gatillo:</strong> se pregunta por un riesgo o una frecuencia y hay un caso reciente o vívido a mano<br>• <strong>Ambiente donde acierta:</strong> lo que de verdad ocurre mucho deja más recuerdos<br>• Se nota cuando la reunión discute con ejemplos y no con cuentas<br>• Y cuando el peligro sube o baja según lo que salió esta semana en el grupo de mensajes"}, "enfermedades": {"title": "Dónde se cae", "info": "• <strong>Modo de fallo:</strong> la facilidad del recuerdo también sube por lo reciente, lo vívido, lo cercano y lo publicado<br>• Lichtenstein y sus colegas (1978) midieron cómo se abultan las causas espectaculares y se encogen las calladas<br>• Y hay un fallo por el otro lado: <strong>lo que fracasó no dejó ejemplo que recordar</strong> (sesgo del superviviente)<br>• Resultado: medidas caras contra peligros raros, y problemas frecuentes que nadie arregla"}, "cuidados": {"title": "En esta casa", "info": "• El susto se contesta con la cuenta escrita en <strong>frecuencias naturales</strong>: cuántos casos, entre cuántas aulas, en cuántos meses<br>• Antes de copiar una receta se pregunta por los que la probaron y ya no están<br>• Y ninguna medida se aprueba la misma semana del caso que la inspiró"}}, "utilidad": {"nombre": "Anclaje con ajuste insuficiente", "icon": "⚓", "estructura": {"title": "Qué es", "info": "• Se parte de una cifra que está a la vista y se ajusta desde ella, <strong>siempre menos de lo que haría falta</strong><br>• La pregunta difícil («¿cuánto vale?») se cambia por «¿cuánto me alejo de este número?»<br>• En 1974, una rueda de la fortuna trucada movió las estimaciones sobre países africanos en la ONU: <strong>25 por ciento tras ver el 10, 45 tras ver el 65</strong><br>• De ella sale el poder de la primera cifra en cualquier mesa"}, "funcion": {"title": "Cómo se reconoce", "info": "• <strong>Gatillo:</strong> aparece un número antes que la cuenta, y da igual de dónde venga<br>• <strong>Ambiente donde acierta:</strong> cuando esa primera cifra sí trae información, como un precio de mercado conocido<br>• Se nota porque la conversación entera se mueve alrededor del número que abrió<br>• Y porque el ajuste se siente como un cálculo, aunque haya empezado en el número ajeno"}, "enfermedades": {"title": "Dónde se cae", "info": "• <strong>Modo de fallo:</strong> el ancla funciona aunque sea arbitraria, y saber que lo es no la desactiva<br>• Cerrar el mismo día en que se oye el primer número<br>• Tomar el precio viejo de la casa como punto de partida: también es un ancla, y encima propia<br>• Creer que basta con «estar prevenido», que es la defensa que no funciona"}, "cuidados": {"title": "En esta casa", "info": "• El precio se calcula <strong>en frío y días antes</strong>, con la cuenta al lado y el mínimo aceptable escrito<br>• Se lleva en papel y se lee antes de contestar nada<br>• Y se ajusta solo con argumentos nuevos, nunca con la distancia al número del otro"}}, "ruina": {"nombre": "Regresión a la media no reconocida", "icon": "📉", "estructura": {"title": "Qué es", "info": "• Tras un resultado extremo, el siguiente tiende a quedar <strong>más cerca del promedio</strong>, sin que nadie haga nada<br>• Ocurre porque en el resultado extremo se juntaron la habilidad y un golpe de suerte, y la suerte no se repite<br>• <strong>Francis Galton</strong> la describió en 1886 midiendo estaturas de padres e hijos<br>• No es una heurística: es el hueco estadístico que la representatividad se apura a llenar con una causa"}, "funcion": {"title": "Cómo se reconoce", "info": "• <strong>Gatillo:</strong> se compara un resultado extremo con el que vino después<br>• Aparece siempre que se selecciona por lo mejor o por lo peor: los primeros bajan y los últimos suben<br>• Se nota en la frase «desde que hicimos X, los mejores empeoraron»<br>• Y en cualquier premio o castigo repartido por un solo resultado"}, "enfermedades": {"title": "Dónde se cae", "info": "• <strong>Modo de fallo:</strong> se lee como efecto de algo lo que era propiedad de los datos<br>• Los instructores de vuelo del ejemplo de 1974 concluyeron que el elogio daña y el regaño ayuda<br>• Sin grupo de comparación, cualquier resultado confirma lo que ya se creía<br>• Y se pagan horas de trabajo por corregir algo que se movía solo"}, "cuidados": {"title": "En esta casa", "info": "• Ningún cambio en la aplicación se aprueba mirando solo a los que estaban en un extremo<br>• Se compara con alumnos de puntaje igual de extremo que <strong>no</strong> recibieron el cambio<br>• Y se dice en voz alta la frase que evita la trampa: <strong>esto no prueba que elogiar dañe, prueba que la estadística existe</strong>"}}};
let labParte='esperado',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`⚙️ Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

// ===================== LECTURAS (normas 5, 5-quater y 5-quinquies) =====================
// Seis textos (Borges, Cervantes, Harari, la entrevista de la casa, la
// conversación Quintero-Gala y el careo) con tres baterías: comprensión (30,
// cinco por voz), completar (12) y análisis complejo (12, sin XP a propósito).
// El armado en pantalla lo hace js/lecturas.js leyendo estos bancos; aquí
// viven los bancos y la impresión. Las preguntas se contestan con los textos
// delante: son examen de lectura, no de memoria.
const lectComprensionBank=[{"t":"Borges","q":"«Yo no adivino», le corrige Lascano al narrador la primera tarde. ¿Con qué compara entonces su método?","o":["a) Con un padrón que él mismo levantaba casa por casa","b) Con una galería de retratos, uno por oficio, delante de la cual va poniendo al hombre que le describen","c) Con una balanza que pesa las virtudes de cada hombre","d) Con un almanaque donde tenía apuntados a todos los vecinos"],"c":1},{"t":"Borges","q":"El martes en que todos dijeron bibliotecario y el hombre resultó ser agricultor, ¿qué le enseñó Lascano al narrador en su cuaderno?","o":["a) Que en la comarca había un bibliotecario y, según el padrón, más de trescientos agricultores","b) Que el escribiente había leído mal la descripción","c) Que ya había fallado otras veces con ese mismo párrafo","d) Que pensaba retirarse del juego esa misma tarde"],"c":0},{"t":"Borges","q":"¿Cuánto tiempo pasó en una celda el forastero detenido por los sacos de grano, y cómo era el culpable verdadero?","o":["a) Dos semanas, y era un vecino conocido de todos","b) Cuatro meses, y era otro forastero todavía más hosco","c) Cuatro meses, y era el que no se parecía a nada","d) Un año, y nunca llegó a saberse quién fue"],"c":2},{"t":"Borges","q":"¿Qué relación descubrió Lascano entre lo largo del párrafo que le leían y la persona descrita en él?","o":["a) Que cuanto más largo era el párrafo, más seguros estaban todos y menos frecuente tenía que ser esa persona","b) Que los párrafos largos describen siempre a gente de ciudad","c) Que los párrafos cortos eran los que más engañaban","d) Que la longitud no cambiaba nada, solo el tono del que leía"],"c":0},{"t":"Borges","q":"En el segundo cuaderno, el que llamaba el libro de los errores, ¿qué cambió Lascano y qué le ocurrió a su fama?","o":["a) Se puso a describir él mismo a los desconocidos, y su fama se hundió del todo","b) Escribía cuántos había de cada oficio en la comarca antes de dejar que le leyeran el párrafo; sus aciertos subieron y su fama bajó","c) Empezó a cobrar por cada acierto, y su fama siguió igual","d) Dejó de anotar los fallos, y su fama creció por el misterio"],"c":1},{"t":"Cervantes","q":"¿Cuánto ofreció maese Gaspar por el par de bueyes de Toribio y en cuánto cerraron el trato?","o":["a) Ofreció ciento veinte reales y cerraron en ciento sesenta y cinco","b) Ofreció ciento sesenta y cinco y cerraron en doscientos","c) Ofreció cuatrocientos y cerraron en trescientos veinte","d) Ofreció doscientos y cerraron en doscientos veinte"],"c":0},{"t":"Cervantes","q":"¿En cuánto traía Toribio los bueyes cuando entró por la puerta de la venta, y qué le hace ver el licenciado Requena?","o":["a) En ciento veinte, y que el chalán le había leído el pensamiento","b) En doscientos, y que había ganado poco para lo que valían","c) En cuatrocientos, y que no subió de ciento veinte a ciento sesenta y cinco, sino que bajó de cuatrocientos a ciento sesenta y cinco","d) En trescientos veinte, y que la feria de Medina pagaba menos ese año"],"c":2},{"t":"Cervantes","q":"En la prueba de la torre de la iglesia, ¿qué fue lo único distinto entre Berrocal y el arriero?","o":["a) Que uno la miró dos veces y el otro una sola","b) Que el número que el licenciado les puso delante antes de que abrieran la boca fue distinto: veinte varas para uno y ochenta para el otro","c) Que Berrocal entendía de varas y el arriero no","d) Que uno la midió de día y el otro ya de noche"],"c":1},{"t":"Cervantes","q":"¿Cuál es el remedio que propone la ventera, y por cuánto daba ella el papel y la tinta?","o":["a) Ser más listo que el chalán, y no cobraba nada por decirlo","b) No hablar nunca de dinero dentro de la venta, y cobraba un real por el consejo","c) Pedirle al licenciado que regateara en nombre de uno, y lo hacía de balde","d) Escribir el precio en un papel antes de entrar por la puerta, y lo daba por un maravedí"],"c":3},{"t":"Cervantes","q":"¿Qué ocurrió a la mañana siguiente con Ginés, el labrador de los cuatro bueyes?","o":["a) Se negó a vender y siguió camino a Medina","b) Dijo cuatrocientos ochenta reales antes que el chalán, cerraron en trescientos veinte y maese Gaspar se fue diciendo a voces que había hecho el negocio de su vida","c) Pidió doscientos y el chalán le pagó doscientos veinte sin discutir","d) Escribió su precio en el papel, pero se le olvidó mirarlo cuando llegó el momento"],"c":1},{"t":"Harari","q":"¿Cómo define el ensayo al cerebro humano en su primera línea?","o":["a) Como una calculadora lenta que la selección natural no llegó a terminar","b) Como una máquina de tener razón, aunque tarde en llegar a ella","c) Como una máquina de contestar a tiempo, que no es lo mismo que una máquina de tener razón","d) Como una máquina de recordar lo que conviene recordar"],"c":2},{"t":"Harari","q":"Según el ensayo, ¿qué mostró Abraham Wald en 1943 con los aviones que volvían del combate?","o":["a) Que había que blindar exactamente donde estaban los agujeros","b) Que el blindaje había que ponerlo en las zonas sin agujeros, porque los aviones tocados ahí no volvían a contarlo","c) Que los aviones más dañados eran los mejor pilotados","d) Que el blindaje no compensaba su peso en ningún caso"],"c":1},{"t":"Harari","q":"¿Qué encontró en 2014 el proyecto Many Labs sobre el anclaje, y qué etiqueta de estatus le pone el ensayo?","o":["a) Que no replicaba, y lo etiqueta de dudoso","b) Que replicaba solo con estudiantes, y lo etiqueta de limitado","c) Que replicaba únicamente con agentes inmobiliarios, y lo deja sin etiqueta","d) Que es de los efectos que replican con más fuerza, y lo etiqueta de sólido y replicado"],"c":3},{"t":"Harari","q":"¿Qué dice el ensayo del estudiante que se pasa un semestre memorizando la lista de sesgos de Wikipedia?","o":["a) Que sale sabiendo doscientos nombres y ninguna idea, porque casi todos son casos particulares de tres máquinas","b) Que es el camino más rápido para dominar esta materia","c) Que le faltará memorizar además el autor y el año de cada uno","d) Que la lista es tan corta que el ejercicio resulta trivial"],"c":0},{"t":"Harari","q":"Según el ensayo, ¿dónde está la única palanca que la evidencia respalda?","o":["a) En la fuerza de voluntad de quien decide","b) En aprenderse el nombre de cada sesgo para reconocerlo a tiempo","c) En el procedimiento y en el ambiente: escribir el número antes de la reunión, contar casos antes de mirar la descripción, preguntar por la tasa antes de reaccionar","d) En la sofisticación cognitiva, que según el texto sí reduce los sesgos"],"c":2},{"t":"Entrevista","q":"De sus años en el ejército, ¿qué prefiere Tversky que se cuente, en lugar del episodio de la carga explosiva?","o":["a) Que allí aprendió a calcular distancias por radio","b) Que bajo fuego se ve a mucha gente decidir, y lo que se ve no es que decidan mal, sino que se equivocan de la misma manera: un error compartido no es ruido, es un mecanismo","c) Que fue oficial y paracaidista en tres guerras","d) Que fue allí donde conoció a Daniel Kahneman"],"c":1},{"t":"Entrevista","q":"¿Cómo describe Tversky el trabajo con Kahneman a partir de 1969, en la Universidad Hebrea de Jerusalén?","o":["a) Repartían el trabajo por capítulos y luego lo juntaban","b) Cada uno escribía su versión por separado y elegían la mejor","c) Encargaban los experimentos y discutían solo los resultados","d) Trabajaban los dos en una habitación, escribiendo una frase por hora, haciéndose las preguntas primero a sí mismos: cuando los dos se equivocaban igual, sospechaban que habían encontrado algo"],"c":3},{"t":"Entrevista","q":"En el ejemplo de los dos hospitales que Tversky recuerda, ¿cuál registra más días con más del sesenta por ciento de varones nacidos?","o":["a) El grande, el de unos cuarenta y cinco partos al día","b) Los dos por igual, que es lo que contesta la mayoría de la gente","c) El pequeño, el de unos quince partos al día, porque las muestras chicas se desvían más","d) Depende de la época del año en que se cuente"],"c":2},{"t":"Entrevista","q":"¿Por qué dice Tversky que la frase sobre la estupidez natural le ha traído más problemas que citas?","o":["a) Porque la palabra estupidez es un chiste y la gente se la lleva a casa como si fuera la tesis, cuando la tesis es la contraria","b) Porque nunca la dijo y se la atribuyeron","c) Porque ofendió a los investigadores de la inteligencia artificial","d) Porque la dijo Kahneman y a él le tocó defenderla"],"c":0},{"t":"Entrevista","q":"¿Con qué dato cierra Punset la entrevista, advirtiendo que el invitado no llegó a conocerlo?","o":["a) Con la beca de la Fundación MacArthur de 1984","b) Con la publicación de la teoría de las perspectivas en «Econometrica», en 1979","c) Con el Premio Nobel de Economía que recibió Daniel Kahneman en 2002 por el trabajo conjunto, y con que el Nobel no se concede a título póstumo","d) Con la fecha exacta del artículo de «Science» de 1974"],"c":2},{"t":"Quintero y Gala","q":"Según Gala, ¿qué fue lo que cambió cuando dejó el Derecho por la literatura y la misma gente empezó a tomarlo por un señorito con veleidades?","o":["a) Que cambió él, y por eso lo trataron distinto","b) Que no cambió él: cambió el retrato con el que lo estaban comparando","c) Que cambió su manera de vestir y de hablar","d) Que dejó de entrar en los sitios donde lo conocían"],"c":1},{"t":"Quintero y Gala","q":"¿Qué dice Gala que añade el artículo de 1974 a lo que en su pueblo ya se sabía con un «tiene cara de»?","o":["a) Nada: solo le pone nombres largos a lo de siempre","b) La prueba de que el parecido acierta casi siempre","c) La factura: dice cuánto se paga por ese vistazo","d) Un método para mirar mejor las caras"],"c":2},{"t":"Quintero y Gala","q":"¿Qué observa Gala sobre los desastres lentos y sobre los que se salvaron?","o":["a) Que los desastres lentos se recuerdan mejor porque duran más","b) Que los desastres lentos no dan fotografía, y que los que se salvaron escriben libros con su receta mientras los otros no escriben nada","c) Que los que se salvaron casi nunca cuentan cómo lo hicieron","d) Que la prensa reparte los ejemplos con bastante exactitud"],"c":1},{"t":"Quintero y Gala","q":"¿Qué hace Gala con las cartas que lo halagan, y cómo llama a esa costumbre?","o":["a) Las contesta enseguida, y lo llama cortesía","b) Las guarda sin abrir, y lo llama disciplina","c) No las contesta el mismo día, y dice que eso no es virtud, es fontanería","d) Se las lee en voz alta a sus amigos, y lo llama humildad"],"c":2},{"t":"Quintero y Gala","q":"¿Por qué dice Gala que una brújula torcida es la única buena noticia de todo este asunto?","o":["a) Porque con el uso acaba enderezándose sola","b) Porque una brújula torcida termina señalando el norte por casualidad","c) Porque la torcedura desaparece en cuanto uno la conoce","d) Porque a un error que cae siempre del mismo lado se le puede restar, y el que va perdido de verdad es el que se desvía cada día para otra parte"],"c":3},{"t":"Debate","q":"¿Cuál es la pregunta en disputa que la moderación escribe antes de empezar?","o":["a) Si la gente es tonta o solamente está mal informada","b) Si conviene decidir por corazonada o con un procedimiento escrito","c) Si el desvío sistemático es un defecto de la mente que hay que compensar o un desajuste entre el problema y el formato en que se plantea","d) Si el problema de Linda debió publicarse tal como se publicó"],"c":2},{"t":"Debate","q":"¿Qué hicieron Gigerenzer y Hoffrage en 1995, según la objeción?","o":["a) Repitieron el problema de Linda con muchos más participantes","b) Reescribieron el problema bayesiano clásico en frecuencias naturales, de cada mil mujeres tantas, y el rendimiento subió de manera espectacular","c) Demostraron que los médicos no saben matemáticas","d) Midieron el punto ciego del sesgo en profesionales"],"c":1},{"t":"Debate","q":"¿Qué le concede la objeción a la defensa en su réplica, y con qué palabras?","o":["a) Que el problema de Linda es indiscutible tal como se publicó","b) Que las frecuencias naturales no cambian nada en la práctica","c) Lo del anclaje: es el efecto más robusto del catálogo y no se explica por el lenguaje","d) Que la lista de sesgos está bien construida y no crece sin control"],"c":2},{"t":"Debate","q":"En el artículo de 2009 que la moderación llama terreno común, ¿en qué se pusieron de acuerdo Kahneman y Klein?","o":["a) En que el juicio rápido no merece confianza en ninguna circunstancia","b) En que el juicio rápido merece confianza cuando el ambiente es regular y da retroalimentación pronta y clara, y no la merece cuando el ambiente es ruidoso o el resultado llega tarde","c) En que la lista de sesgos hay que cerrarla de una vez","d) En que avisar a alguien de sus sesgos es la intervención más eficaz que existe"],"c":1},{"t":"Debate","q":"¿Qué dato dice la moderación que resolvería lo que sigue en disputa?","o":["a) Una encuesta amplia sobre qué sesgos reconoce la gente en sí misma","b) Un metaanálisis de los estudios de laboratorio ya publicados","c) Un experimento nuevo con estudiantes y apuestas pequeñas","d) Un programa preinscrito que ponga las mismas decisiones reales a las mismas personas en los dos formatos, probabilidades y frecuencias naturales, con consecuencias de verdad y seguimiento en el tiempo, midiendo sesgo por sesgo"],"c":3}];
const lectCompletarBank=[{"t":"Borges","q":"«El retrato manda y el ___ se calla», anotó Lascano el martes en que todos dijeron bibliotecario.","a":"censo"},{"t":"Borges","q":"Escribió Lascano que un hombre que toca la flauta es menos raro que un hombre que toca la flauta, cría ___ y odia el mar.","a":"abejas"},{"t":"Cervantes","q":"Dice el licenciado que el primer número que cae en una mesa no es un número: es una ___ que clava uno en el suelo y a la que se atan después todas las sogas.","a":"estaca"},{"t":"Cervantes","q":"La ventera tenía papel y tinta para escribir el precio antes de entrar, y lo daba por un ___.","a":"maravedí"},{"t":"Harari","q":"El blindaje de los aviones había que ponerlo en las zonas sin ___, porque los aviones tocados ahí no volvían a contarlo.","a":"agujeros"},{"t":"Harari","q":"La lista de sesgos cognitivos de Wikipedia ronda las ___ entradas, y crece.","a":"doscientas"},{"t":"Entrevista","q":"Cuenta Tversky que en su casa de Haifa había una madre diputada y un padre ___.","a":"veterinario"},{"t":"Entrevista","q":"Dice Tversky que la palabra ___ es un chiste, y que la gente se la lleva a casa como si fuera la tesis.","a":"estupidez"},{"t":"Quintero y Gala","q":"Gala dice que él puede parecerse mucho a un ___ y ser una cosa mucho más frecuente y mucho más pobre.","a":"cardenal"},{"t":"Quintero y Gala","q":"De su costumbre de no contestar el mismo día las cartas que lo halagan dice Gala que eso no es virtud: es ___.","a":"fontanería"},{"t":"Debate","q":"La postura que contesta a la defensa en el careo es la de la racionalidad ___.","a":"ecológica"},{"t":"Debate","q":"El dato que resolvería la disputa sería un programa ___, con el método declarado antes de recoger nada.","a":"preinscrito"}];
const lectAnalisisBank=[{"t":"Borges","q":"Lascano dedicó su vejez a un segundo cuaderno, el libro de los errores, donde invirtió el orden de sus operaciones: primero el censo de la comarca y después la descripción. Explica qué corrige ese cambio de orden y por qué sus aciertos subieron mientras su fama bajaba.","guia":"Se valora que se nombre lo que el orden nuevo corrige, que es la ceguera a la tasa base, y que se apoye en las dos frases del propio cuento: que el parecido no sabe contar y que el retrato manda mientras el censo se calla. Una respuesta buena explica que la descripción no queda anulada sino puesta en su sitio, tal como dice Lascano al afirmar que solo corrige un poco al censo, y que por eso la contestación acertada acaba siendo muchas veces la aburrida, agricultor tres veces seguidas. Se valora también quien vea la ironía del desenlace, que la fama vivía del asombro y no del acierto, y quien saque de ahí alguna consecuencia propia sobre qué se premia en la conversación de todos los días."},{"t":"Borges","q":"El forastero pasó cuatro meses en una celda y nadie del pueblo recordó ese error. Relaciona ese episodio con el aforismo 46 del «Novum Organum» de Francis Bacon que el cuento cita, y con la confesión del narrador en la última página.","guia":"Se valora que los tres momentos se lean como el mismo mecanismo visto tres veces. El pueblo guarda los aciertos porque son los que quedan para ser contados, igual que en Bacon quedan los cuadros votivos de los que se salvaron y faltan los de quienes se ahogaron habiendo hecho las mismas promesas. Una respuesta buena señala que el error no desapareció: dejó de ser recordado, que es distinto, y que por eso el juego seguía pareciendo infalible desde fuera. Se valora especialmente quien recoja la confesión final del narrador, que su propia historia le gustó demasiado y que una historia que le queda a uno tan bien casi nunca es la más frecuente sino la más parecida a lo que uno quería contar, y quien explique por qué esa confesión cierra el cuento en vez de estropearlo."},{"t":"Cervantes","q":"El licenciado Requena le dice a Toribio que no subió de ciento veinte a ciento sesenta y cinco, sino que bajó de cuatrocientos a ciento sesenta y cinco. Explica cómo pueden ser verdad las dos cosas a la vez y qué papel juega el número que nunca llegó a salir de su boca.","guia":"Se valora que se distinga el movimiento visible del movimiento real. Medido desde la primera oferta del chalán, Toribio ganó cuarenta y cinco reales y por eso se acostó ufano; medido desde el precio con el que había entrado por la puerta, perdió doscientos treinta y cinco sin enterarse, porque su cifra se quedó dentro de la cabeza y la del otro se quedó encima de la mesa. Una respuesta buena usa la imagen de la estaca y las sogas: quien llega sin estaca propia se ata a la ajena y encima se marcha contento de lo mucho que ha tirado de la soga. Se valora quien note que aquí no hay ningún engaño ni ningún tonto, solo un ajuste que arranca del número ajeno y se detiene antes de llegar, y quien lo diga sin convertir el atajo en estupidez."},{"t":"Cervantes","q":"La ventera dice que el remedio no es ser listo, que listos entran muchos y salen desplumados todos, y que su remedio es de pobre. Explica en qué consiste y por qué el desenlace de maese Gaspar al día siguiente le da la razón.","guia":"Se valora que el remedio se cuente entero y en su orden: el precio escrito en un papel antes de entrar por la puerta, y la costumbre de mirar el papel y no la cara del que habla cuando el otro dice su número. Una respuesta buena explica por qué eso no depende de tener labia ni reflejos, que es justamente lo que la ventera señala al llamarlo remedio de pobre: lo que se decide en frío no lo descompone el que habla primero. Y se valora sobre todo quien aproveche bien el desenlace de maese Gaspar, que no es tonto ni novato, que traía doscientos reales en el bolsillo y la intención de no pasar de doscientos veinte, y que acabó pagando trescientos veinte y marchándose convencido de haber hecho el negocio de su vida: la prueba de que conocer el oficio no basta cuando la primera cifra la dice otro."},{"t":"Harari","q":"El ensayo subraya la palabra sistemáticos del resumen de 1974 y dice que ahí está la diferencia entre errar y errar siempre hacia el mismo lado. Explica qué se puede hacer con un error sistemático que no se puede hacer con uno cualquiera, y ejemplifícalo con uno de los tres atajos.","guia":"Se valora que se llegue a la consecuencia práctica y no solo a la definición: un error que cae siempre del mismo lado se puede prever antes de cometerlo y por tanto se le puede montar encima un procedimiento, mientras que un error que va cada vez para otra parte solo se puede lamentar después. Una respuesta buena aterriza en un atajo concreto con el remedio que el propio texto le pone: escribir el número antes de entrar a la reunión si lo que va a aparecer es el anclaje, contar cuántos hay antes de mirar el parecido si es la representatividad, preguntar por la tasa antes de reaccionar a la noticia si es la disponibilidad. Se valora quien no confunda prever con impedir, porque el ensayo dice con todas las letras que el atajo va a aparecer igual y que lo que se cambia no es la aguja sino la ruta."},{"t":"Harari","q":"La mala noticia del ensayo es que saber todo esto no inmuniza, y la sostiene con dos estudios. Cítalos con su año y con lo que midieron, y explica por qué el texto concluye que la palanca no está en la voluntad sino en el procedimiento y el ambiente.","guia":"Se valora que los dos estudios entren con su año y con lo que cada uno midió: en 2002, Pronin, Lin y Ross y el punto ciego del sesgo, esa convicción tranquila de que los sesgos los tienen los demás; en 2012, West, Meserve y Stanovich, y el resultado de que la sofisticación cognitiva no lo reduce. Una respuesta buena saca la consecuencia incómoda que el texto saca, que los que más saben se creen más inmunes, y por eso no admite ninguna versión del proponerse estar atento. Se valora que la palanca se describa como algo que se monta fuera de la cabeza y antes de la decisión, con los ejemplos del propio ensayo, incluidas las frecuencias naturales que Gigerenzer y Hoffrage mostraron en 1995. No se valora ninguna respuesta que prometa que conocer el nombre de un sesgo lo apaga, porque es exactamente lo que el texto niega."},{"t":"Entrevista","q":"A la última pregunta de Punset, sobre si conocer estos sesgos protege de ellos, Tversky contesta que muy poco y que quien prometa otra cosa está vendiendo algo. Explica la razón que da y desarrolla la imagen con la que cierra: no se corrige la brújula con buena voluntad, se le pone al lado un mapa que no dependa de ella.","guia":"Se valora que se recoja la razón que el texto da, y no una moraleja traída de fuera: desde dentro un sesgo no se siente como un sesgo, se siente como la verdad, mientras que en los demás se ve con una nitidez extraordinaria. Una respuesta buena explica qué ocupa entonces el lugar de la buena voluntad, con los tres ejemplos que la entrevista pone: decidir el número antes de la reunión, escribir la estimación antes de conocer el resultado, obligarse a contar cuántos hay antes de mirar a quién se parece. Se valora que la imagen del mapa se lea como lo que es, un instrumento que sigue funcionando aunque la aguja siga desviada, y no como una manera de enderezarla. Una respuesta que concluya que basta con saberse los nombres de los sesgos contradice al entrevistado y a la etapa entera."},{"t":"Entrevista","q":"La nota que encabeza esta lectura avisa de que la objeción de Hertwig y Gigerenzer se publicó en 1999, tres años después de la muerte de Tversky, y de que la respuesta que aquí se le atribuye es invención de la casa. Explica por qué la lectura declara ese aviso y qué habría que corregir si alguien citara esa respuesta como una posición documentada.","guia":"Se valora que se separe con limpieza lo comprobable de lo inventado. Comprobable: que Tversky murió en 1996, que la objeción de Hertwig y Gigerenzer se publicó en 1999, y que su contenido es el que la entrevista describe, la ambigüedad de la palabra probable en el habla corriente y la caída de las violaciones al preguntar en frecuencias. Inventado: la conversación entera y, señaladamente, la contestación que se le pone en la boca a un hombre que no pudo llegar a leer esa objeción. Una respuesta buena dice qué corrección haría falta: citar la objeción por su fuente y su año y no atribuirle al entrevistado ninguna postura sobre ella. Se valora quien conecte esto con la etiqueta de estatus que esta materia exige para cada estudio, y quien explique por qué una hoja suelta que viajara sin ese aviso sería justo la fuente inflada que aquí se enseña a cazar."},{"t":"Quintero y Gala","q":"Gala responde que uno no se cura, que uno se organiza, y pone como ejemplo su costumbre de no contestar el mismo día las cartas que lo halagan. Explica qué diferencia hay entre curarse y organizarse, y por qué dice que eso no es virtud.","guia":"Se valora que la distinción quede en pie sin suavizarla: curarse sería dejar de tener el atajo, y Gala niega que eso ocurra empezando por sí mismo, cuando dice que sabe que es vanidoso y que no se ha vuelto humilde por saberlo. Organizarse es montar de antemano una costumbre que decida en lugar de uno justo en el momento en que uno decidiría mal. Una respuesta buena explica por qué lo llama fontanería y no virtud: no hace falta ser mejor persona para que funcione, solo hace falta que la regla esté puesta antes y no dependa del ánimo de esa tarde. Se valora quien recoja la frase de que la costumbre escrita es lo único que sigue funcionando cuando uno está cansado, que es precisamente cuando la cabeza tira por el atajo, y quien proponga una costumbre propia con esa misma forma."},{"t":"Quintero y Gala","q":"Desarrolla la imagen con la que Gala cierra la conversación: una brújula torcida no miente, se desvía siempre hacia el mismo lado, y a un error así se le puede restar. Di qué le pide entonces a su cabeza, qué no le pide, y qué dos condiciones pone para que la imagen sirva de algo.","guia":"Se valora que se vea por qué aquí la constancia es mejor noticia que la justicia: a un error constante se le puede aplicar una corrección fija, mientras que el que se desvía cada día para otra parte no deja restar nada, y de ahí que Gala no le pida a su cabeza que sea justa, que no lo va a ser, sino que sea constante, que ya lo es. Una respuesta buena recoge las dos condiciones que el texto pone y que impiden leer la imagen como un consuelo: saber de cuánto es la torcedura, es decir haberla medido, y tener la honradez de no olvidar la brújula en el cajón las noches en que conviene olvidarla. Se valora quien enlace ese cierre con lo que Gala ya había dicho sobre el número escrito de casa y la cuenta hecha en frío, porque son esa resta puesta en práctica."},{"t":"Debate","q":"Reconstruye las dos posturas del careo en su mejor versión, con los estudios en que se apoya cada una, y di qué le concede cada lado al otro en las réplicas.","guia":"Se valora que las dos posturas queden escritas como las firmaría su mejor defensor antes de que quien contesta opine, que es la regla del acero antes del juicio. La defensa: los tres atajos descritos en «Science» en 1974, la palabra sistemáticos como clave porque un error predecible se puede compensar, el problema de Linda de 1983 como prueba de que un juicio de plausibilidad puede pisar una regla lógica sin que quien juzga note nada, y el argumento de que el mundo reparte los problemas con formatos malos y no acepta reclamaciones. La objeción: las frecuencias naturales de Gigerenzer y Hoffrage en 1995, la ambigüedad de la palabra probable en Hertwig y Gigerenzer en 1999, y la tesis de «Simple Heuristics That Make Us Smart» de que una heurística es una herramienta con su ecología. Las concesiones: la defensa acepta entero el efecto de las frecuencias naturales y lo llama receta y no refutación; la objeción concede el anclaje por robusto y por no explicarse con el lenguaje. Se penaliza cualquier reconstrucción escrita para perder."},{"t":"Debate","q":"La moderación sostiene que las dos posturas discuten menos de lo que parece y que lo que sigue en disputa es sobre cómo llamar a lo que pasa. Enumera el terreno común que declara y explica por qué el dato que pediría para cerrar la disputa tiene que ser preinscrito y con consecuencias de verdad.","guia":"Se valora que el terreno común salga completo y no resumido en una frase: que los desvíos existen y se miden, que son sistemáticos y por tanto predecibles, que las frecuencias naturales son mejor formato que las probabilidades condicionales y hay que enseñarlas, que avisar a alguien de que tiene un sesgo hace muy poco, y que la palanca está en el procedimiento y el ambiente y no en el esfuerzo de voluntad de quien decide. Una respuesta buena apoya ese terreno en el documento que la moderación cita, el de Kahneman y Klein de 2009 con su subtítulo sobre el fracaso en el intento de estar en desacuerdo, y en la condición que allí se acordó: ambiente regular y retroalimentación pronta y clara. Sobre el dato, se valora que se expliquen las dos exigencias por separado, el método declarado antes de recoger nada para que el resultado no se elija después de verlo, y las consecuencias reales para no medir a gente que contesta sin jugarse nada, más el detalle de medir el tamaño del efecto sesgo por sesgo y no en promedio."}];
/* Las tres baterías de pantalla las monta ahora js/lecturas.js dentro de
   cada lectura, leyendo estos mismos bancos por su etiqueta de voz. */

/* ---------- impresión: cada lectura por separado ---------- */
// La etiqueta del estatus viaja SIEMPRE con el texto impreso. Con las dos
// entrevistas la etiqueta crece: además del pastiche hay que declarar que el
// encuentro nunca ocurrió, porque una hoja suelta se fotocopia y viaja sola,
// y una entrevista apócrifa sin declarar es un parte falso con buena cara.
const LECTURAS_IMPR={
  borges:{titulo:'El adivinador de oficios',tipo:'Cuento, a la manera de Jorge Luis Borges'},
  cervantes:{titulo:'Donde se cuenta la venta de un par de bueyes en una venta del camino de Medina, y de cómo el que dice el primer número tiene ganada la mitad del pleito antes de empezarlo, con lo que sobre ello sentenció la ventera',tipo:'Capítulo, a la manera de Miguel de Cervantes Saavedra'},
  harari:{titulo:'Tres atajos y un zoológico',tipo:'Ensayo, a la manera de Yuval Noah Harari'},
  entrevista:{titulo:'El hombre que descubrió que nos equivocamos en fila',tipo:'Entrevista imaginada con Amos Tversky, a la manera de Eduard Punset',ficcion:true},
  gala:{titulo:'El que se parece paga',tipo:'El Loco de la Colina: Jesús Quintero conversa con Antonio Gala (conversación imaginada)',ficcion:true},
  debate:{titulo:'¿La mente falla o el ambiente no encaja?',tipo:'Careo: las dos posturas de una disputa abierta, con sus réplicas',careo:true},
};
function _etiquetaImpresa(meta){
  if(meta&&meta.careo){
    return '<div class="etiqueta"><strong>⚖️ Careo escrito por la casa sobre una disputa real.</strong> Los turnos los firman los <strong>papeles</strong> (moderación, defensa, objeción) y no personas: aquí no se le pone a nadie una palabra en la boca. Los investigadores se citan en tercera persona como fuentes, <strong>toda obra, revista, fecha y cifra es real y comprobable</strong>, y cada postura va escrita en su mejor versión, no en la que sería fácil de tumbar.</div>';
  }
  if(meta&&meta.ficcion){
    return '<div class="etiqueta"><strong>⚠️ Entrevista imaginada: ejercicio de estilo de la casa, en homenaje.</strong> El encuentro <strong>nunca ocurrió</strong>: lo escribió el Proyecto Educativo F.A.R.O. imitando las voces. Las personas son reales, <strong>toda obra, fecha y cifra citada es real y comprobable</strong>, y lo único inventado es la conversación.</div>';
  }
  return '<div class="etiqueta"><strong>⚠️ Ejercicio de estilo de la casa, en homenaje.</strong> Este texto <strong>NO es obra de ese autor</strong>: lo escribió el Proyecto Educativo F.A.R.O. imitando su voz, y se declara como pastiche. Regla extra de la casa: <strong>toda obra, fecha y persona citada dentro del texto es real y comprobable</strong>; el único artificio permitido es la voz.</div>';
}
function _hojaImpresa(titulo,cuerpo,pieExtra){
  return `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>${titulo} · Tres atajos generan el zoológico · F.A.R.O.</title><style>
@page{size:letter;margin:16mm 15mm;}
*{margin:0;padding:0;box-sizing:border-box;}
body{font-family:Georgia,'Times New Roman',serif;font-size:11.5pt;line-height:1.55;color:#111;background:#fff;}
h1{font-family:Arial,Helvetica,sans-serif;font-size:15pt;color:#1a2e05;margin-bottom:2mm;line-height:1.2;}
.tipo{font-family:Arial,Helvetica,sans-serif;font-size:9.5pt;color:#555;margin-bottom:3mm;}
.ruta{font-family:Arial,Helvetica,sans-serif;font-size:9pt;color:#4d7c0f;border-bottom:1.5pt solid #4d7c0f;padding-bottom:1.5mm;margin-bottom:3mm;display:flex;justify-content:space-between;gap:6mm;}
.etiqueta{border:1.2pt solid #4d7c0f;background:#f7fee7;border-radius:2mm;padding:2.5mm 3mm;font-family:Arial,Helvetica,sans-serif;font-size:9pt;line-height:1.4;margin-bottom:4mm;}
.idline{font-family:Arial,Helvetica,sans-serif;font-size:9pt;display:flex;gap:4mm;margin-bottom:3mm;}
.idline span.r{flex:1;border-bottom:0.8pt solid #666;}
p.t{text-align:justify;margin-bottom:2.6mm;text-indent:6mm;}
p.t:first-of-type{text-indent:0;}
h2{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#1a2e05;margin:4mm 0 2mm;}
.sec{font-family:Arial,Helvetica,sans-serif;font-size:10.5pt;font-weight:700;color:#4d7c0f;background:#f7fee7;border-left:3pt solid #4d7c0f;padding:1.2mm 2.5mm;margin:4mm 0 2mm;}
.q{font-family:Arial,Helvetica,sans-serif;font-size:10pt;margin:2mm 0 1mm;}
.q .n{font-weight:700;color:#4d7c0f;}
.op{font-family:Arial,Helvetica,sans-serif;font-size:9.5pt;margin-left:7mm;}
.ln{border-bottom:0.8pt solid #888;height:6.5mm;}
.ln-alta{border-bottom:0.8pt solid #888;height:9mm;}
.fuente{font-family:Arial,Helvetica,sans-serif;font-size:8.5pt;color:#555;font-style:italic;}
.pauta{page-break-before:always;}
.pl{font-family:Arial,Helvetica,sans-serif;font-size:9pt;margin-bottom:1.6mm;text-align:justify;}
.pie{border-top:0.8pt solid #999;margin-top:5mm;padding-top:2mm;font-family:Arial,Helvetica,sans-serif;font-size:8.5pt;color:#555;display:flex;justify-content:space-between;gap:6mm;}
${FaroMarcador.cssImpresion()}
</style></head><body>${cuerpo}<div class="pie"><span>🏠 Proyecto Educativo F.A.R.O. · Estudio Mayor</span><span>🧭 Tres atajos generan el zoológico${pieExtra||''}</span></div></body></html>`;
}
function _abreImpresion(doc){
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}
function imprimirLectura(clave){
  const meta=LECTURAS_IMPR[clave];const card=document.getElementById('lect-'+clave);
  if(!meta||!card){showToast('⚠️ No se encontró la lectura');return;}
  sfx('click');
  const nota=card.querySelector('.lect-nota');
  const parrafos=[...card.querySelectorAll('.lect-p')].map(p=>'<p class="t">'+p.innerHTML+'</p>').join('');
  const cuerpo=`<div class="ruta"><span>🧭 Ruta de la Brújula Torcida · Etapa 1 de 6</span><span>Lecturas 📖</span></div>`
    +`<h1>${meta.titulo}</h1><div class="tipo">${meta.tipo}</div>`
    +_etiquetaImpresa(meta)
    +`<div class="idline"><span>Lee:</span><span class="r"></span><span>Fecha:</span><span class="r" style="max-width:35mm"></span></div>`
    +(nota?`<p class="fuente">${nota.textContent}</p>`:'')
    +parrafos;
  const _ap=window.FaroLecturas;
  const preg=(_ap&&_ap.preguntasImpresas)?_ap.preguntasImpresas(clave):'';
  const _cuerpo=(_ap&&_ap.etiquetaCareo)?_ap.etiquetaCareo(clave,cuerpo):cuerpo;
  _abreImpresion(_hojaImpresa(meta.titulo,_cuerpo+preg+FaroMarcador.impresionExtra([clave]),' · '+meta.titulo));
}
function imprimirTodasLasLecturas(){
  sfx('click');
  let cuerpo=`<div class="ruta"><span>🧭 Ruta de la Brújula Torcida · Etapa 1 de 6</span><span>Las seis lecturas 📖</span></div>`
    +`<h1>Las seis lecturas de «Tres atajos generan el zoológico»</h1><div class="tipo">Un cuento, un capítulo, un ensayo, dos entrevistas imaginadas y un careo, sobre los mismos tres atajos</div>`
    +`<div class="etiqueta"><strong>⚠️ Ejercicios de estilo de la casa, en homenaje.</strong> Los cinco primeros <strong>NO son obra de Jorge Luis Borges, de Miguel de Cervantes Saavedra ni de Yuval Noah Harari</strong>, el sexto es un careo escrito por la casa sobre una disputa real, y las dos entrevistas son <strong>imaginadas: los encuentros nunca ocurrieron</strong>. La entrevista de la casa y la conversación entre Jesús Quintero y Antonio Gala son invención del Proyecto Educativo F.A.R.O., que se declara como pastiche. Las personas son reales y <strong>toda obra, fecha y cifra citada dentro de los textos es real y comprobable</strong>; el único artificio permitido es la voz.</div>`;
  ['borges','cervantes','harari','entrevista','gala','debate'].forEach((clave,i)=>{
    const meta=LECTURAS_IMPR[clave];const card=document.getElementById('lect-'+clave);
    if(!card)return;
    const nota=card.querySelector('.lect-nota');
    cuerpo+=(i?'<div style="page-break-before:always;"></div>':'')
      +`<h2>${i+1}. ${meta.titulo}</h2><div class="tipo">${meta.tipo}</div>`
      +(nota?`<p class="fuente">${nota.textContent}</p>`:'')
      +[...card.querySelectorAll('.lect-p')].map(p=>'<p class="t">'+p.innerHTML+'</p>').join('');
  });
  _abreImpresion(_hojaImpresa('Las seis lecturas',cuerpo+FaroMarcador.impresionExtra(null),' · Las seis lecturas'));
}
function imprimirPreguntasLecturas(){
  sfx('click');
  const lineas=(n,alta)=>Array(n).fill('<div class="'+(alta?'ln-alta':'ln')+'"></div>').join('');
  let cuerpo=`<div class="ruta"><span>🧭 Ruta de la Brújula Torcida · Etapa 1 de 6</span><span>Preguntas de las lecturas 📖</span></div>`
    +`<h1>Preguntas de las seis lecturas</h1><div class="tipo">Tres atajos generan el zoológico · 30 de comprensión lectora, 12 de completar y 12 de análisis complejo</div>`
    +`<div class="idline"><span>Nombre:</span><span class="r"></span><span>Fecha:</span><span class="r" style="max-width:35mm"></span></div>`
    +`<div class="etiqueta">Se responde <strong>con los seis textos delante</strong>: no es un examen de memoria. Las respuestas de las tres secciones van en la <strong>pauta de la última hoja</strong>, así que se resuelve antes de darle la vuelta. Los cinco primeros son <strong>ejercicios de estilo de la casa</strong>: no son obra de Borges, Cervantes ni Harari, y las dos entrevistas son imaginadas (los encuentros nunca ocurrieron). El sexto es un <strong>careo</strong> sobre una disputa real, con los turnos firmados por papeles y no por personas.</div>`;
  cuerpo+='<div class="sec">I. Comprensión lectora (30 preguntas)</div>';
  lectComprensionBank.forEach((q,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${q.q} <span class="fuente">(${q.t})</span></div>`;
    q.o.forEach(o=>{cuerpo+=`<div class="op">${o}</div>`;});
  });
  cuerpo+='<div class="sec">II. Completa la oración (12 preguntas)</div>';
  lectCompletarBank.forEach((d,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${d.q.replace('___','_______________')} <span class="fuente">(${d.t})</span></div>`;
  });
  cuerpo+='<div class="sec">III. Análisis complejo (12 preguntas)</div>';
  lectAnalisisBank.forEach((d,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${d.q}</div>`+lineas(3,true);
  });
  cuerpo+='<div class="pauta"><div class="sec">✅ Pauta completa de respuestas</div>';
  cuerpo+='<div class="pl"><strong>I. Comprensión lectora:</strong> '+lectComprensionBank.map((q,i)=>(i+1)+') '+'abcd'[q.c]).join(' · ')+'</div>';
  cuerpo+='<div class="pl"><strong>II. Completar:</strong> '+lectCompletarBank.map((d,i)=>(i+1)+') '+d.a).join(' · ')+'</div>';
  cuerpo+='<div class="pl" style="margin-top:2mm;"><strong>III. Análisis complejo (guías de corrección):</strong></div>';
  lectAnalisisBank.forEach((d,i)=>{cuerpo+=`<div class="pl"><strong>${i+1}.</strong> ${d.guia}</div>`;});
  cuerpo+='</div>';
  _abreImpresion(_hojaImpresa('Preguntas de las lecturas',cuerpo,' · Preguntas de las lecturas'));
}

